suppressPackageStartupMessages(library(data.table));w<-'independent_validation';blue<-'#4C78A8';ink<-'#303030';grey<-'#B7BEC4';orange<-'#C47A39';light<-'#E4E7E9'
v<-fread(file.path(w,'HepG2_gene_effects.tsv'))[mode=='exact_Lminus_target'];s<-fread('reconstruction/cross_dataset/phase2_upr_rpe1/source_rank_inputs.tsv');rk<-fread('reconstruction/cross_dataset/phase2_upr_rpe1/all_source_comparator_rankings.tsv');a<-merge(v,s[,.(gene,source=source_UPR_deltaZ)],by='gene');b<-merge(rk[method=='UPR_priority'&rank<=20,.(gene,rank)],v,by='gene')[order(rank)];m<-fread(file.path(w,'all_fixed_baseline_metrics.tsv'))[mode=='exact_Lminus_target'&minimum_cells==10];null<-fread(file.path(w,'all100_module_priority_metrics.tsv'))[mode=='exact_Lminus_target'&minimum_cells==10];unif<-fread(file.path(w,'uniform10000_reference_draws.tsv.gz'))[mode=='exact_Lminus_target'&minimum_cells==10];rr<-fread(file.path(w,'all_ordering_results.tsv'))[mode=='exact_Lminus_target'&minimum_cells==30]
fwrite(a,file.path(w,'figure_panel_a_source.tsv'),sep='\t');fwrite(b,file.path(w,'figure_panel_b_source.tsv'),sep='\t');fwrite(m,file.path(w,'figure_panel_c_source.tsv'),sep='\t');fwrite(null,file.path(w,'figure_panel_d_source.tsv'),sep='\t')
panel<-function(x,t){mtext(x,3,line=2.0,adj=0,font=2,cex=1.15);mtext(t,3,line=.55,adj=0,cex=.95)}
draw<-function(){par(mfrow=c(2,2),family='Helvetica',ps=7.5,cex=1,mgp=c(2.3,.55,0),tcl=-.2,col=ink,col.axis=ink,col.lab=ink,las=1)
 par(mar=c(4.5,4.5,3.1,.8));plot(a$source,a$effect,type='n',xlab='Frozen K562 UPR effect (control SD)',ylab='HepG2 UPR effect (control SD)',bty='l');abline(h=0,v=0,col=light,lwd=.6);points(a$source,a$effect,pch=16,cex=.45,col=ifelse(a$cells>=30,adjustcolor(blue,.65),orange));legend('topleft',legend=c(sprintf('Primary: n = %d; rho = %.3f',rr$genes,rr$rho),sprintf('95%% gene interval [%.3f, %.3f]',rr$low,rr$high),'Orange: fewer than 30 cells'),bty='n',cex=.9);panel('a','Independent response ordering')
 par(mar=c(4.5,6.1,3.1,.8));yy<-rev(seq_len(20));plot(b$cells,yy,type='n',log='x',xlim=c(10,220),ylim=c(.4,20.6),axes=FALSE,xlab='HepG2 cells per frozen candidate',ylab='');axis(1,at=c(10,30,100,200),labels=c(10,30,100,200));axis(2,at=yy,labels=paste0(b$rank,'  ',b$gene),cex.axis=.84);box(bty='l');abline(v=30,col=ink,lty=2,lwd=.7);segments(10,yy,b$cells,yy,col=light);points(b$cells,yy,pch=16,cex=.7,col=ifelse(b$cells<30,orange,blue));text(b$cells[b$cells<30]*1.18,yy[b$cells<30],b$cells[b$cells<30],cex=.85,col=orange);panel('b','Two candidates miss primary support')
 par(mar=c(4.5,8.8,3.1,.8));mm<-c('UPR_priority','raw_UPR','generic_magnitude','DepMap','expression','count','genomewide_annotation');labs<-c('UPR + agreement','Simple UPR effect','Three-program norm','Essentiality','Source expression','Cell support','Annotation');plot(NA,xlim=c(0,1),ylim=c(.5,7.5),axes=FALSE,xlab='NDCG on common 370-gene panel',ylab='');axis(1,at=seq(0,1,.25));axis(2,at=7:1,labels=labs,cex.axis=.9);box(bty='l');for(k in c(10,20)){z<-m[K==k];points(z$NDCG[match(mm,z$method)],7:1,pch=if(k==10)16 else 1,col=if(k==10)blue else ink,cex=.8)};legend('topright',legend=c('Top 10','Top 20'),pch=c(16,1),col=c(blue,ink),bty='n',cex=.9);panel('c','Low-support sensitivity: simple baselines')
 par(mar=c(4.5,4.5,3.1,.8));plot(NA,xlim=c(.6,2.4),ylim=c(0,1),axes=FALSE,xlab='Frozen source-list size',ylab='NDCG on HepG2 UPR outcome');axis(1,at=1:2,labels=c('Top 10','Top 20'));axis(2,at=seq(0,1,.25));box(bty='l');set.seed(2026110704);for(i in 1:2){k<-c(10,20)[i];z<-null[K==k,NDCG];points(rep(i,length(z))+runif(length(z),-.12,.12),z,pch=16,cex=.42,col=adjustcolor(grey,.6));q<-m[method=='UPR_priority'&K==k,NDCG];segments(i-.16,q,i+.16,q,col=blue,lwd=1.5);points(i,q,pch=18,col=blue,cex=.9);u<-mean(unif[K==k,NDCG]);segments(i-.16,u,i+.16,u,lty=3,col=ink)};legend('topright',legend=c('UPR priority','100 matched-module priorities','Uniform-order mean'),pch=c(18,16,NA),lty=c(NA,NA,3),col=c(blue,grey,ink),bty='n',cex=.85);panel('d','Low-support sensitivity: random references')
}
if(Sys.info()[['sysname']]=='Darwin')quartz(type='pdf',file=file.path(w,'Fig_UPR_independent_HepG2.pdf'),width=183/25.4,height=170/25.4,family='Helvetica',pointsize=7.5)else cairo_pdf(file.path(w,'Fig_UPR_independent_HepG2.pdf'),width=183/25.4,height=170/25.4,family='Helvetica',pointsize=7.5);draw();dev.off();svglite::svglite(file.path(w,'Fig_UPR_independent_HepG2.svg'),width=183/25.4,height=170/25.4);draw();dev.off();ragg::agg_png(file.path(w,'Fig_UPR_independent_HepG2_preview.png'),width=183,height=170,units='mm',res=200,pointsize=7.5);draw();dev.off();writeLines(capture.output(sessionInfo()),file.path(w,'figure_sessionInfo.txt'))
